    dp[0][0][0][0] = grid[0][0]

    # Fill the DP table
    for r1 in range(N):
        for c1 in range(N):
            for r2 in range(N):
                for c2 in range(N):
                    if r1 > 0 and r2 > 0:
                        dp[r1][c1][r2][c2] = max(dp[r1-1][c1][r2-1][c2], dp[r1-1][c1][r2][c2-1], dp[r1][c1-1][r2-1][c2], dp[r1][c1-1][r2][c2-1])
