                    dp[i][j-1][k-1],
                    dp[i][j-1][k]
                ) + curr_value

    return dp[N][N][N]

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    from collections import defaultdict

    # Parse grid values into a dictionary for quick lookup
    grid = defaultdict(int)
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[(x-1, y-1)] = value

    # Initialize DP table
    dp = [[[-float('inf')] * N for _ in range(N)] for _ in range(N * 2 - 1)]

    # Base case
    dp[0][0][0] = grid[(0, 0)]

    # Fill DP table
    for step in range(1, 2 * N - 1):
        for i1 in range(max(0, step - (N - 1)), min(step + 1, N)):
            i2 = step - i1
            if i2 >= N:
                continue
            for j1 in range(N):
                j2 = step - j1
                if j2 >= N:
                    continue
                # Skip invalid grid positions
                if (i1, j1) not in grid or (i2, j2) not in grid:
                    continue
                value = grid[(i1, j1)] + (grid[(i2, j2)] if i1 != i2 or j1 != j2 else 0)
                if i1 > 0 and i2 > 0:
                    dp[step][i1][j1] = max(dp[step][i1][j1], dp[step-1][i1-1][j1] + value)
                    dp[step][i1][j1] = max(dp[step][i1][j1], dp[step-1][i1][j1-1] + value)
                    dp[step][i1][j1] = max(dp[step][i1][j1], dp[step-1][i1-1][j1-1] + value)
