def max_product(num_str: str, N: int, K: int) -> int:
    if not num_str.isdigit() or N <= 0 or K < 0 or K >= N:
        raise ValueError("Invalid input: num_str must be a digit string, N must be positive, and 0 <= K < N.")

    def product_of_list(nums):
        product = 1
        for num in nums:
            product *= int(num)
        return product

    def backtrack(start, path):
        if len(path) == K + 1:
            products.append(product_of_list(path))
            return
        for i in range(start + 1, N - (K - len(path))):
            backtrack(i, path + [num_str[start:i]])
        if start < N:
            path.append(num_str[start:])
            backtrack(N, path)
            path.pop()

    products = []
    backtrack(0, [])
    return max(products)

