    def split_and_multiply(parts):
        product = 1
        for part in parts:
            if part:  # Avoid multiplying by empty string
                product *= int(part)
        return product

    def backtrack(start, k, current_parts):
        if k == 0:
            current_parts.append(num_str[start:])
            max_product_value = split_and_multiply(current_parts)
            current_parts.pop()
            return max_product_value

        max_product_value = 0
        for i in range(start + 1, N - k + 2):
            current_parts.append(num_str[start:i])
            max_product_value = max(max_product_value, backtrack(i, k - 1, current_parts))
            current_parts.pop()

        return max_product_value

    return backtrack(0, K, [])

