    if any(not (1 <= x <= M and 1 <= y <= N and 1 <= p <= M and 1 <= q <= N) for x, y, p, q in chatting_pairs):
        raise ValueError("Chatting pairs are out of bounds")

    horizontal_separations = [0] * (M + 1)
    vertical_separations = [0] * (N + 1)

