        if x == p:
            if y < q:
                vertical_separations[y] += 1
            else:
                vertical_separations[q] += 1
        elif y == q:
            if x < p:
                horizontal_separations[x] += 1
            else:
                horizontal_separations[p] += 1

    # Find the K best horizontal positions
    horizontal_aisles = sorted(range(1, M + 1), key=lambda i: horizontal_separations[i], reverse=True)[:K]
    # Find the L best vertical positions
    vertical_aisles = sorted(range(1, N + 1), key=lambda j: vertical_separations[j], reverse=True)[:L]

