def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("Number of students must be positive and number of passes must be non-negative.")
    if n == 1:
        return 1 if m == 0 else 0

    # dp[i][j] will be the number of ways to reach student j after i passes
    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1

    for i in range(1, m + 1):
        for j in range(n):
            dp[i][j] = dp[i - 1][(j - 1) % n] + dp[i - 1][(j + 1) % n]

    return dp[m][0]

def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m < 0:
        raise ValueError("The number of students must be greater than 0 and the number of passes must be non-negative.")
    if n == 1:
        return 1 if m % 2 == 0 else 0

    # dp[i][j] will be the number of ways to pass the ball to student i in j passes
    dp = [[0] * (m + 1) for _ in range(n)]
    dp[0][0] = 1  # starting point

    for passes in range(1, m + 1):
        for student in range(n):
            # The ball can come from the left neighbor (student - 1) or the right neighbor (student + 1)
            left_neighbor = (student - 1) % n
            right_neighbor = (student + 1) % n
            dp[student][passes] = dp[left_neighbor][passes - 1] + dp[right_neighbor][passes - 1]

    return dp[0][m]

