def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V < 0 or n < 0 or any(v < 0 for v in volumes):
        raise ValueError("Volume, number of items, and item volumes must be non-negative.")
    if n != len(volumes):
        raise ValueError("The number of items must match the length of the volumes list.")

    # Initialize a DP array where dp[i] is True if a subset with volume i can be formed
    dp = [False] * (V + 1)
    dp[0] = True  # A subset with volume 0 is always possible (empty subset)

    for volume in volumes:
        # Traverse backwards to avoid using the same item multiple times
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    # Find the maximum volume that can be formed which is less than or equal to V
    max_occupied_volume = max(i for i, can_form in enumerate(dp) if can_form)

    return V - max_occupied_volume

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    if V < 0 or n < 0 or any(v < 0 for v in volumes):
        raise ValueError("Volume, number of items, and all item volumes must be non-negative.")
    if n != len(volumes):
        raise ValueError("The number of items must match the length of the volumes list.")

    dp = [False] * (V + 1)
    dp[0] = True

    for v in volumes:
        for j in range(V, v - 1, -1):
            if dp[j - v]:
                dp[j] = True

    max_occupied = next((j for j in range(V, -1, -1) if dp[j]), 0)

    return V - max_occupied

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(1, min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

