    dp = [0] * (m + 1)
    dp[0] = 1  # There is one way to arrange 0 pots: use no pots at all

    # Iterate over each flower type
    for i in range(n):
        # Create a prefix sum array to avoid recalculating sums
        prefix_sum = [0] * (m + 1)
        for j in range(1, m + 1):
            prefix_sum[j] = (prefix_sum[j - 1] + dp[j]) % MOD

        # Update the dp array for the current flower type
        for j in range(m, -1, -1):
            if j > 0:
