def mod_inverse(a, b):
    def extended_gcd(a, b):
        if a == 0:
            return b, 0, 1
        gcd, x1, y1 = extended_gcd(b % a, a)
        x = y1 - (b // a) * x1
        y = x1
        return gcd, x, y

    try:
        gcd, x, _ = extended_gcd(a, b)
        if gcd != 1:
            return None
        else:
            return x % b
    except Exception as e:
        return None

