                lis[i] = max(lis[i], lis[j] + 1)

    # Compute LDS values from right to left
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[i] > heights[j]:
                lds[i] = max(lds[i], lds[j] + 1)

    # The maximum value of lis[i] + lds[i] - 1 gives the length of the longest
    # choir formation possible
    max_choir_length = max(lis[i] + lds[i] - 1 for i in range(n))

    # The minimum number of students to leave is the total number of students
    # minus the length of the longest choir formation
    return n - max_choir_length

